package org.mockito.internal.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Timer_isCounting_TriageGen0Test {

    @Test
    public void testIsCounting_TrueWhenWithinDuration() throws InterruptedException {
        // Arrange
        long duration = 500L;
        Timer timer = new Timer(duration);
        timer.start();

        // Act
        boolean result = timer.isCounting();

        // Assert
        assertTrue("Should be counting immediately after start", result);
    }

    @Test
    public void testIsCounting_TrueWhenNearEnd() throws InterruptedException {
        // Arrange
        long duration = 100L;
        Timer timer = new Timer(duration);
        timer.start();

        // Sleep for slightly less than duration
        Thread.sleep(50L);

        // Act
        boolean result = timer.isCounting();

        // Assert
        assertTrue("Should still be counting before duration expires", result);
    }

    @Test
    public void testIsCounting_FalseWhenDurationExpired() throws InterruptedException {
        // Arrange
        long duration = 10L;
        Timer timer = new Timer(duration);
        timer.start();

        // Act
        // Sleep longer than the duration to ensure expiration
        Thread.sleep(30L);
        boolean result = timer.isCounting();

        // Assert
        assertFalse("Should not be counting after duration has passed", result);
    }

    @Test(expected = AssertionError.class)
    public void testIsCounting_ThrowsAssertionErrorWhenNotStarted() {
        // Arrange
        Timer timer = new Timer(1000L);

        // Act
        // Calling isCounting before start() should trigger 'assert startTime != -1'
        timer.isCounting();
    }
}
